function plan({ values, previous }) {
  if (!Array.isArray(values)) throw Error("Expected full sheet values");
  if (!values.length) return { snapshot: [], changed: false, text: "unused" };
  const headers = values[0];
  if (!Array.isArray(headers)) throw Error("Missing header row");
  const names = ["Security Code", "Price", "Quantity"],
    indexes = names.map((n) => headers.indexOf(n));
  if (indexes.some((v, i) => v < 0 || headers.lastIndexOf(names[i]) !== v))
    throw Error("Sheet needs unique Security Code, Price and Quantity headers");
  const rows = values.slice(1).map((row) => {
    if (!Array.isArray(row)) throw Error("Malformed sheet row");
    return names.map((_, i) => String(row[indexes[i]] ?? ""));
  });
  const current = rows.map((r) => r[0]);
  if (
    previous !== null &&
    (!Array.isArray(previous) || previous.some((x) => typeof x !== "string"))
  )
    throw Error("Invalid saved sheet state");
  const changed =
    previous !== null && current.some((v, i) => i >= previous.length || v !== previous[i]);
  if (!changed) return { snapshot: current, changed: false, text: "unused" };
  const printable = rows.filter((r) => r.some(Boolean));
  const safe = (s) =>
    s
      .replace(/[\r\n\t]/g, " ")
      .replace(/`/g, "ˋ")
      .replace(/@/g, "@\u200b");
  const all = [names, ...printable].map((row) => row.map(safe)),
    width = names.map((_, i) => Math.max(...all.map((r) => r[i].length)));
  const text =
    "```\n" +
    all.map((row) => row.map((s, i) => s.padEnd(width[i])).join("  ")).join("\n") +
    "\n```";
  if (text.length > 2000) throw Error("Table exceeds Discord message limit");
  return { snapshot: current, changed: true, text };
}

const s = $getWorkflowStaticData("node");
const x = plan({ values: $input.first().json.values ?? [], previous: s.codes ?? null });
s.codes = x.snapshot;
return [{ json: x }];
